import { globalattrDetail, globalattrSave } from "@/api/system/relationManage";
export default {
  props: ['isShow', 'arrtId', 'showType'],
  data: function data() {
    return {
      submitForm: {},
      rules: {
        name: [{
          required: true,
          message: '名称不能为空',
          trigger: 'blur'
        }]
      },
      pageLoading: false,
      saveLoading: false,
      searchForm: {
        currentPage: 1,
        pageSize: 20
      },
      total: 0,
      configTableData: [],
      //配置项列表
      configTableCol: [],
      //列表表头
      tableLoading: false,
      //表格加载
      tableHeight: undefined
    };
  },
  mounted: function mounted() {
    // this.getDetail()
    this.configTableData = [{
      attrEntityData: {
        attr_idd1: {
          valueList: [111]
        },
        attr_idd2: {
          valueList: [111]
        },
        attr_idd3: {
          valueList: [111]
        },
        attr_idd4: {
          valueList: [111]
        },
        attr_idd5: {
          valueList: [111]
        },
        attr_idd6: {
          valueList: [111]
        }
      },
      globalAttrEntityData: {}
    }];
    this.configTableCol = [{
      key: "attr_idd1",
      title: "文本框1"
    }, {
      key: "attr_idd2",
      title: "文本框2"
    }, {
      key: "attr_idd3",
      title: "文本框3"
    }, {
      key: "attr_idd4",
      title: "文本框4"
    }, {
      key: "attr_idd5",
      title: "文本框5"
    }, {
      key: "attr_idd6",
      title: "文本框6"
    }];
  },
  methods: {
    handleRefresh: function handleRefresh() {},
    handleChooseDevice: function handleChooseDevice() {},
    // 详情
    getDetail: function getDetail() {
      var _this = this;
      if (this.showType != '新增') {
        this.pageLoading = true;
        globalattrDetail({
          id: this.arrtId
        }).then(function (res) {
          _this.pageLoading = false;
          _this.submitForm = res.Return;
        }).catch(function () {
          _this.pageLoading = false;
        });
      }
    },
    // 保存
    save: function save() {
      var _this2 = this;
      this.$refs.submitForm.validate(function (valid) {
        if (valid) {
          _this2.saveLoading = true;
          globalattrSave(_this2.submitForm).then(function (res) {
            _this2.saveLoading = false;
            _this2.$message({
              type: 'success',
              message: '保存成功！'
            });
            _this2.$emit('saveGlobalArrt');
          }).catch(function () {
            _this2.saveLoading = false;
          });
        }
      });
    }
  }
};
